// pubspec.yaml:
//   http: ^1.2.0

import 'package:http/http.dart' as http;

// 1. FUNCTIONAL — one-shot; creates a Client per call (no connection reuse).
final r1 = await http.get(Uri.parse('https://api.example.com/users'));
print(r1.statusCode);   // 200
print(r1.body);         // raw string; you decode
final users = jsonDecode(r1.body) as List;

// 2. Reused CLIENT — keeps sockets alive, big cellular win.
final client = http.Client();
try {
  await client.get(Uri.parse('https://api/x'));
  await client.get(Uri.parse('https://api/y'));
} finally {
  client.close();       // MANDATORY — leaks sockets otherwise.
}

// 3. POST JSON.
final r2 = await client.post(
  Uri.parse('https://api/orders'),
  headers: {'Content-Type': 'application/json', 'Authorization': 'Bearer $token'},
  body: jsonEncode({'item': 'widget', 'qty': 2}),
);

// 4. STREAMED response for big downloads.
final req = http.Request('GET', Uri.parse('https://api/big.zip'));
final resp = await client.send(req);   // StreamedResponse
final sink = File('/tmp/big.zip').openWrite();
await resp.stream.pipe(sink);

// 5. Multipart upload.
final mp = http.MultipartRequest('POST', Uri.parse('https://api/upload'))
  ..headers['Authorization'] = 'Bearer $token'
  ..fields['category'] = 'avatar'
  ..files.add(await http.MultipartFile.fromPath('file', path));
final streamed = await client.send(mp);
final body = await streamed.stream.bytesToString();

// http has NO built-in timeout on send/receive. You wrap with Future.timeout.
try {
  final r = await client.get(uri).timeout(const Duration(seconds: 10));
} on TimeoutException {
  // fall back / show error
}

// CANCEL: create a request, wrap client, close it. Any in-flight request throws.
final cancelClient = http.Client();
final future = cancelClient.get(uri);
// Later, from another callback:
cancelClient.close();   // Throws ClientException in the pending future.

// Screen-scoped pattern:
class _S extends State<Feed> {
  final _client = http.Client();
  Future<void> _load() async { await _client.get(uri); }
  @override void dispose() { _client.close(); super.dispose(); }
}

// Attach auth + logging to every request without touching call sites.
class AuthLoggingClient extends http.BaseClient {
  AuthLoggingClient(this._inner, this._tokens);
  final http.Client _inner;
  final TokenStore _tokens;

  @override
  Future<http.StreamedResponse> send(http.BaseRequest req) async {
    req.headers['Authorization'] = 'Bearer ${_tokens.access}';
    final sw = Stopwatch()..start();
    final resp = await _inner.send(req);
    print('[${resp.statusCode}] ${req.method} ${req.url} in ${sw.elapsedMilliseconds}ms');

    if (resp.statusCode == 401) {
      await _tokens.refresh();
      final retry = _cloneRequest(req);
      retry.headers['Authorization'] = 'Bearer ${_tokens.access}';
      return _inner.send(retry);
    }
    return resp;
  }

  http.BaseRequest _cloneRequest(http.BaseRequest r) {
    // Non-trivial: bodies are streams; you need to buffer for retry — one of the reasons Dio wins.
    if (r is http.Request) {
      final clone = http.Request(r.method, r.url)
        ..headers.addAll(r.headers)
        ..bodyBytes = r.bodyBytes;
      return clone;
    }
    throw UnsupportedError('cannot clone streamed request');
  }

  @override void close() { _inner.close(); }
}

// dev_dependencies: http: ^1.2.0  (MockClient is in http/testing.dart)
import 'package:http/testing.dart';

final mock = MockClient((req) async {
  if (req.url.path == '/users') return http.Response('[{"id":1}]', 200);
  if (req.url.path == '/me' && req.method == 'GET') return http.Response('{"error":"expired"}', 401);
  return http.Response('not found', 404);
});

final api = UserApi(client: mock);
final list = await api.list();
